"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { BRAND } from "@/lib/brand";
import type { HeroSlide } from "@/lib/content/sections";
import { toneFor } from "../Frame";
import styles from "./CinematicHero.module.css";

export function HeroCarousel({ slides, isPageTitle = true }: { slides: HeroSlide[]; isPageTitle?: boolean }) {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [visible, setVisible] = useState(true);
  const [reduced, setReduced] = useState(false);
  const root = useRef<HTMLElement>(null);
  const pointer = useRef<{ x: number; y: number } | null>(null);
  const swiped = useRef(false);
  const count = slides.length;
  const active = count ? index % count : 0;
  const move = (delta: number) => setIndex(value => (value + delta + count) % count);
  useEffect(() => {
    const preference = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(preference.matches);
    update(); preference.addEventListener("change", update);
    const observer = new IntersectionObserver(([entry]) => setVisible(Boolean(entry?.isIntersecting)), { threshold: .15 });
    if (root.current) observer.observe(root.current);
    return () => { observer.disconnect(); preference.removeEventListener("change", update); };
  }, []);
  useEffect(() => {
    if (count < 2 || paused || hovered || focused || !visible || reduced || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const timer = setInterval(() => setIndex(value => (value + 1) % count), 7000);
    return () => clearInterval(timer);
  }, [count, paused, hovered, focused, visible, reduced]);
  if (!count) return null;
  return <section ref={root} className={styles.hero} aria-label="Featured collections" aria-roledescription="carousel"
    onMouseEnter={() => setHovered(true)} onMouseLeave={() => setHovered(false)}
    onFocusCapture={() => setFocused(true)} onBlurCapture={event => { if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false); }}
    onKeyDown={event => { if (event.key === "ArrowRight") { event.preventDefault(); move(1); } if (event.key === "ArrowLeft") { event.preventDefault(); move(-1); } }}>
    {isPageTitle && <h1 className="sr-only">{BRAND.name} — handwoven Banarasi textiles</h1>}
    {slides.map((slide, i) => <div key={slide.id} className={styles.scene} data-active={i === active} data-ink={slide.ink || "light"} data-align={slide.align || "left"} aria-hidden={i !== active} inert={i !== active}>
      <Link href={slide.ctaHref} className={styles.photo} aria-label={`Explore ${slide.title}`} style={{ backgroundColor: toneFor(slide.art.desktop.tone) }}
        onPointerDown={event => { pointer.current = { x: event.clientX, y: event.clientY }; swiped.current = false; }}
        onPointerUp={event => { const start = pointer.current; pointer.current = null; if (!start) return; const dx = event.clientX - start.x; if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(event.clientY - start.y)) { swiped.current = true; move(dx < 0 ? 1 : -1); } }}
        onPointerCancel={() => { pointer.current = null; }} onDragStart={event => event.preventDefault()}
        onClickCapture={event => { if (swiped.current) { event.preventDefault(); swiped.current = false; } }}>
        {slide.art.desktop.src && <Image src={slide.art.desktop.src} alt={slide.title} fill sizes="100vw" loading={i === 0 ? "eager" : "lazy"} fetchPriority={i === 0 ? "high" : "auto"} className={slide.art.mobile.src !== slide.art.desktop.src ? styles.desktop : undefined} />}
        {slide.art.mobile.src && slide.art.mobile.src !== slide.art.desktop.src && <Image src={slide.art.mobile.src} alt={slide.title} fill sizes="100vw" className={styles.mobile} />}
      </Link>
      <div className={styles.scrim} aria-hidden="true" />
      <div className={styles.caption}>
        {slide.eyebrow && <p className={styles.eyebrow}>{slide.eyebrow}</p>}
        <h2>{slide.title}</h2><p className={styles.description}>{slide.body}</p>
        <Link href={slide.ctaHref} className={styles.cta}>{slide.ctaLabel}<span aria-hidden="true">↗</span></Link>
      </div>
    </div>)}
    <div className={styles.topline} aria-hidden="true"><span>{BRAND.name} / Collections</span><span>Woven in Banaras</span></div>
    {count > 1 && <div className={styles.controls} data-playing={!paused && !hovered && !focused && visible && !reduced}>
      <div className={styles.selectors}>{slides.map((slide, i) => <button key={slide.id} className={styles.selector} aria-label={`Show ${slide.title}`} aria-pressed={i === active} onClick={() => setIndex(i)}><span>{String(i + 1).padStart(2,"0")}</span><span className={styles.track} key={`${active}-${i}`} /></button>)}</div>
      <div className={styles.arrows}><button aria-label={paused ? "Play slideshow" : "Pause slideshow"} aria-pressed={paused} onClick={() => setPaused(value => !value)}>{paused ? "▷" : "Ⅱ"}</button><button aria-label="Previous slide" onClick={() => move(-1)}>←</button><button aria-label="Next slide" onClick={() => move(1)}>→</button></div>
    </div>}
  </section>;
}
